static int pack_can_0x067_EdgeEnums(can_obj_bitfield_edge_h_t *o, uint64_t *data) {
	assert(o);
	assert(data);
	if (o->can_id != 0x067)
		memset(&o->messages, 0, sizeof(o->messages));
	register uint64_t x;
	register uint64_t i = 0;
	/* inline_enum: start-bit 3, length 3, endianess intel, scaling 1, offset 0 */
	x = ((uint8_t)(o->messages.can_0x067_EdgeEnums.inline_enum)) & 0x7;
	x <<= 3; 
	i |= x;
	/* mode: start-bit 0, length 2, endianess intel, scaling 1, offset 0 */
	x = ((uint8_t)(o->messages.can_0x067_EdgeEnums.mode)) & 0x3;
	i |= x;
	/* state: start-bit 2, length 1, endianess intel, scaling 1, offset 0 */
	x = ((uint8_t)(o->messages.can_0x067_EdgeEnums.state)) & 0x1;
	x <<= 2; 
	i |= x;
	*data = (i);
	o->can_id = 0x067;
	return 2;
}

static int unpack_can_0x067_EdgeEnums(can_obj_bitfield_edge_h_t *o, uint64_t data, uint8_t dlc) {
	assert(o);
	assert(dlc <= 8);
	register uint64_t x;
	register uint64_t i = (data);
	if (dlc < 2)
		return -1;
	/* inline_enum: start-bit 3, length 3, endianess intel, scaling 1, offset 0 */
	x = (i >> 3) & 0x7;
	o->messages.can_0x067_EdgeEnums.inline_enum = x;
	/* mode: start-bit 0, length 2, endianess intel, scaling 1, offset 0 */
	x = i & 0x3;
	o->messages.can_0x067_EdgeEnums.mode = x;
	/* state: start-bit 2, length 1, endianess intel, scaling 1, offset 0 */
	x = (i >> 2) & 0x1;
	o->messages.can_0x067_EdgeEnums.state = x;
	o->can_id = 0x067;
	return 2;
}

