static int pack_can_0x068_EdgeMux(can_obj_bitfield_edge_h_t *o, uint64_t *data) {
	assert(o);
	assert(data);
	if (o->can_id != 0x068)
		memset(&o->messages, 0, sizeof(o->messages));
	register uint64_t x;
	register uint64_t i = 0;
	/* mux: start-bit 0, length 8, endianess intel, scaling 1, offset 0 */
	x = ((uint8_t)(o->messages.can_0x068_EdgeMux.mux)) & 0xff;
	i |= x;
	if (o->messages.can_0x068_EdgeMux.mux == 1) {
		/* muxed_a: start-bit 8, length 8, endianess intel, scaling 1, offset 0 */
		x = ((uint8_t)(o->messages.can_0x068_EdgeMux.muxed_a)) & 0xff;
		x <<= 8; 
		i |= x;
	} else if (o->messages.can_0x068_EdgeMux.mux == 2) {
		/* muxed_b: start-bit 8, length 8, endianess intel, scaling 1, offset 0 */
		x = ((uint8_t)(o->messages.can_0x068_EdgeMux.muxed_b)) & 0xff;
		x <<= 8; 
		i |= x;
	} else {
		return -1;
	}
	*data = (i);
	o->can_id = 0x068;
	return 8;
}

static int unpack_can_0x068_EdgeMux(can_obj_bitfield_edge_h_t *o, uint64_t data, uint8_t dlc) {
	assert(o);
	assert(dlc <= 8);
	register uint64_t x;
	register uint64_t i = (data);
	if (dlc < 8)
		return -1;
	/* mux: start-bit 0, length 8, endianess intel, scaling 1, offset 0 */
	x = i & 0xff;
	o->messages.can_0x068_EdgeMux.mux = x;
	if (o->messages.can_0x068_EdgeMux.mux == 1) {
		/* muxed_a: start-bit 8, length 8, endianess intel, scaling 1, offset 0 */
		x = (i >> 8) & 0xff;
		o->messages.can_0x068_EdgeMux.muxed_a = x;
	} else if (o->messages.can_0x068_EdgeMux.mux == 2) {
		/* muxed_b: start-bit 8, length 8, endianess intel, scaling 1, offset 0 */
		x = (i >> 8) & 0xff;
		o->messages.can_0x068_EdgeMux.muxed_b = x;
	} else {
		return -1;
	}
	o->can_id = 0x068;
	return 8;
}

