int unpack_message(can_obj_bitfield_edge_h_t *o, const unsigned long id, uint64_t data, uint8_t dlc) {
	assert(o);
	assert(id < (1ul << 29)); /* 29-bit CAN ID is largest possible */
	assert(dlc <= 8);         /* Maximum of 8 bytes in a CAN packet */
	switch (id) {
	case 0x064: return unpack_can_0x064_EdgePacked(o, data, dlc);
	case 0x065: return unpack_can_0x065_EdgeFloat(o, data, dlc);
	case 0x066: return unpack_can_0x066_EdgeDouble(o, data, dlc);
	case 0x067: return unpack_can_0x067_EdgeEnums(o, data, dlc);
	case 0x068: return unpack_can_0x068_EdgeMux(o, data, dlc);
	default: break; 
	}
	return -1; 
}

int pack_message(can_obj_bitfield_edge_h_t *o, const unsigned long id, uint64_t *data) {
	assert(o);
	assert(id < (1ul << 29)); /* 29-bit CAN ID is largest possible */
	switch (id) {
	case 0x064: return pack_can_0x064_EdgePacked(o, data);
	case 0x065: return pack_can_0x065_EdgeFloat(o, data);
	case 0x066: return pack_can_0x066_EdgeDouble(o, data);
	case 0x067: return pack_can_0x067_EdgeEnums(o, data);
	case 0x068: return pack_can_0x068_EdgeMux(o, data);
	default: break; 
	}
	return -1; 
}

int message_dlc(const unsigned long id) {
	assert(id < (1ul << 29)); /* 29-bit CAN ID is largest possible */
	switch (id) {
	case 0x064: return 8;
	case 0x065: return 8;
	case 0x066: return 8;
	case 0x067: return 2;
	case 0x068: return 8;
	default: break; 
	}
	return -1; 
}

int print_message(const can_obj_bitfield_edge_h_t *o, const unsigned long id, FILE *output) {
	assert(o);
	assert(id < (1ul << 29)); /* 29-bit CAN ID is largest possible */
	assert(output);
	if (o->can_id != id)
		return -1;
	switch (id) {
	case 0x064: return print_can_0x064_EdgePacked(o, output);
	case 0x065: return print_can_0x065_EdgeFloat(o, output);
	case 0x066: return print_can_0x066_EdgeDouble(o, output);
	case 0x067: return print_can_0x067_EdgeEnums(o, output);
	case 0x068: return print_can_0x068_EdgeMux(o, output);
	default: break; 
	}
	return -1; 
}

